export type BrandId = keyof typeof MARKS

/** The bundled mark named `brand`, if there is one. */
export function brandMark(brand: string | null): Mark | null {
  return brand && Object.hasOwn(MARKS, brand) ? MARKS[brand as BrandId] : null
}
